bool canFormPalindrome(string &s)
{
    int count[256] = {0};

    // Count frequency of characters
    for (int i = 0; s[i]; i++)
        count[s[i]]++;

    int odd = 0;

    // Count odd frequencies
    for (int i = 0; i < 256; i++) {
        if (count[i] % 2 != 0)
            odd++;

        if (odd > 1)
            return false;
    }

    return true;
}

